toolScript:
const monitorSpecs = {
            'budget-ips': { srgb: 85, p3: 60, adobe: 58, name: 'Budget IPS' },
            'standard-ips': { srgb: 95, p3: 72, adobe: 74, name: 'Standard IPS' },
            'pro-ips': { srgb: 99, p3: 82, adobe: 88, name: 'Professional IPS' },
            'wide-gamut': { srgb: 95, p3: 95, adobe: 92, name: 'Wide Gamut IPS' },
            'qd-oled': { srgb: 98, p3: 99, adobe: 95, name: 'QD-OLED' },
            'va-standard': { srgb: 90, p3: 65, adobe: 62, name: 'Standard VA' },
            'va-premium': { srgb: 95, p3: 78, adobe: 76, name: 'Premium VA' }
        };
        const usageRecommendations = {
            web: { primary: 'srgb', min: 95, description: 'Web content requires sRGB accuracy for consistent viewing' },
            photo: { primary: 'adobe-rgb', min: 90, description: 'Photography benefits from Adobe RGB coverage for extended gamut editing' },
            video: { primary: 'dci-p3', min: 90, description: 'Video production requires DCI-P3 coverage for modern streaming delivery' },
            gaming: { primary: 'dci-p3', min: 85, description: 'Gaming benefits from wider gamut for more vivid HDR experiences' },
            print: { primary: 'adobe-rgb', min: 92, description: 'Print design requires Adobe RGB and careful soft-proofing practices' },
            broadcast: { primary: 'dci-p3', min: 95, description: 'Broadcast standards require P3 coverage for HDR production workflows' }
        };
        function visualizeGamut() {
            const monitorType = document.getElementById('monitor-type').value;
            const usage = document.getElementById('usage').value;
            const specs = monitorSpecs[monitorType];
            const rec = usageRecommendations[usage];
            document.getElementById('srgb-bar').style.width = specs.srgb + '%';
            document.getElementById('srgb-value').textContent = specs.srgb + '%';
            document.getElementById('p3-bar').style.width = specs.p3 + '%';
            document.getElementById('p3-value').textContent = specs.p3 + '%';
            document.getElementById('adobe-bar').style.width = specs.adobe + '%';
            document.getElementById('adobe-value').textContent = specs.adobe + '%';
            const primaryValue = rec.primary === 'srgb' ? specs.srgb : rec.primary === 'dci-p3' ? specs.p3 : specs.adobe;
            let resultHtml = '<div class="flex justify-between"><span class="opacity-90">Primary Coverage:</span><span class="font-bold">' + primaryValue + '%</span></div>';
            resultHtml += '<div class="flex justify-between"><span class="opacity-90">Target:</span><span class="font-bold">' + rec.min + '%</span></div>';
            resultHtml += '<div class="flex justify-between border-t border-amber-400/30 pt-2 mt-2"><span class="opacity-90">Recommendation:</span><span class="font-bold">' + (primaryValue >= rec.min ? 'Sufficient' : 'Upgrade Needed') + '</span></div>';
            document.getElementById('coverage-results').innerHTML = resultHtml;
            let recHtml = '<div>' + rec.description + '</div>';
            if (primaryValue >= rec.min) {
                recHtml += '<div class="mt-2 text-emerald-600 font-bold">✓ Your monitor meets requirements for ' + (usage === 'web' ? 'web content' : usage === 'photo' ? 'photography' : usage === 'video' ? 'video production' : usage === 'gaming' ? 'gaming' : usage === 'print' ? 'print design' : 'broadcast') + '.</div>';
            } else {
                recHtml += '<div class="mt-2 text-amber-600 font-bold">⚠ Consider upgrading for optimal results.</div>';
            }
            document.getElementById('recommendations').innerHTML = recHtml;
        }
        visualizeGamut();
